/* NOVA individual selling price editor: no stock or purchase mutation. */
(()=>{'use strict';
const make=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n};
const panel=make('section');panel.id='nova-manual-price-editor';panel.hidden=true;
panel.style.cssText='position:fixed;inset:5%;z-index:10010;overflow:auto;direction:rtl;background:#fff;color:#173c44;border-radius:18px;border:1px solid #c3dbdf;padding:24px;box-shadow:0 18px 65px #0006';
const header=make('h2','إدارة أسعار بيع الأصناف');panel.append(header);
panel.append(make('p','ابحث باسم الدواء أو الباركود، ثم عدّل سعر بيع العبوة المطلوبة. لا تتغير الكميات أو الفواتير القديمة.'));
const close=make('button','إغلاق');close.type='button';panel.append(close);
const search=make('input');search.type='search';search.placeholder='اسم الدواء أو الباركود';search.setAttribute('aria-label','بحث عن صنف');search.style.cssText='display:block;width:100%;max-width:550px;padding:12px;border:1px solid #a9c6cb;border-radius:10px;margin:14px 0';panel.append(search);
const info=make('p','اكتب جزءاً من اسم الصنف أو الباركود.');info.setAttribute('role','status');panel.append(info);
const results=make('div');results.style.cssText='display:grid;gap:10px';panel.append(results);
const req=async(path,body)=>{const r=await fetch('/api/v1/'+path,{credentials:'same-origin',method:body?'POST':'GET',headers:{'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'تعذر تنفيذ العملية');return data};
let version=0,pending=false,delay;
const money=v=>Number(v||0).toLocaleString('ar-SD');
const refresh=async()=>{const v=++version,q=search.value.trim();results.replaceChildren();if(q.length<2){info.textContent='اكتب حرفين على الأقل للبحث';return}info.textContent='جارٍ البحث...';try{const data=await req('nova-sale-price-catalog?q='+encodeURIComponent(q));if(v!==version)return;const rows=Array.isArray(data.rows)?data.rows:[];info.textContent=rows.length+' نتيجة (الحد الأقصى 60؛ اكتب اسماً أدق لتضييق النتائج)';for(const item of rows){const card=make('div');card.style.cssText='border:1px solid #d1e3e6;border-radius:12px;padding:12px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap';const detail=make('div');detail.append(make('strong',item.name+' '+(item.strength||'')));detail.append(make('div','العبوة: '+(item.unit_name||'—')+' · الباركود: '+(item.barcode||'—')));detail.append(make('div','سعر البيع الحالي: '+money(item.sale_price)));card.append(detail);const btn=make('button','تعديل سعر البيع');btn.type='button';card.append(btn);btn.onclick=async()=>{if(pending)return;const raw=prompt('السعر الحالي: '+money(item.sale_price)+'\nأدخل سعر البيع الجديد بالأرقام:',String(item.sale_price));if(raw===null)return;const value=raw.trim();if(!/^\d+$/.test(value)||!Number.isSafeInteger(Number(value))||Number(value)<=0){info.textContent='أدخل سعر بيع صحيحاً أكبر من صفر';return}if(Number(value)===Number(item.sale_price)){info.textContent='السعر الجديد مطابق للسعر الحالي';return}if(!confirm('تغيير سعر بيع '+item.name+' من '+money(item.sale_price)+' إلى '+money(value)+'؟'))return;pending=true;btn.disabled=true;try{await req('nova-manual-sale-price',{package_id:item.package_id,old_sale_price:item.sale_price,new_sale_price:Number(value)});info.textContent='تم حفظ السعر بنجاح مع سجل التدقيق';await refresh()}catch(e){info.textContent=e.message}finally{pending=false;btn.disabled=false}};results.append(card)}}catch(e){if(v===version)info.textContent=e.message}};
search.addEventListener('input',()=>{clearTimeout(delay);delay=setTimeout(refresh,250)});
close.onclick=()=>{if(pending)return;panel.hidden=true;version++};
document.addEventListener('DOMContentLoaded',()=>{document.body.append(panel);const launch=make('button','بحث وتعديل سعر صنف');launch.type='button';launch.className='btn outline small';launch.onclick=()=>{panel.hidden=false;search.focus();if(search.value.trim().length>=2)refresh()};const prior=nav;nav=function(page){prior(page);launch.remove();if(!['stock','inventory','prices','products','catalog'].includes(page))return;const root=document.querySelector('main')||document.querySelector('#app');const target=root?.querySelector('.panel-head')||root?.querySelector('.panel');if(target)target.append(launch)};const current=document.querySelector('[data-page].active');if(current)nav(current.getAttribute('data-page'))});
})();